def is_prime(n):
    """Helper function to check if a number is prime"""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    if a < 100:
        return False
    for i in range(2, a):
        if a % i == 0 and is_prime(i):
            a //= i
            if not is_prime(a // i):
                return False
            if a % (a // i) == 0 and is_prime(a // (a // i)):
                return False
    return True

# Example usage:
print(is_multiply_prime(30))  # True, since 30 = 2 * 3 * 5
print(is_multiply_prime(42))  # True, since 42 = 2 * 3 * 7
print(is_multiply_prime(28))  # True, since 28 = 2 * 2 * 7
print(is_multiply_prime(35))  # False, since 35 = 5 * 7 and not a product of three primes
